-- Import av StFF:s föreningslista för Stockholm.
-- Källa: https://www.stff.se/forening/vara-foreningar/
-- Genererad: 2026-08-06
-- Antal föreningar: 367

begin;

on conflict (name, region) do update set
  municipality = excluded.municipality,
  website = excluded.website,
  verified = true,
  updated_at = now();

commit;

select count(*) as stff_stockholm_clubs
from public.clubs
where region = 'Stockholm'
  and website like 'https://www.stff.se/rs/foreningar/%';
